import unittest

from hourglass.rounding import label_rounded, round_minutes
from hourglass.models import Span

class RoundMinutesTests(unittest.TestCase):
    def test_nearest(self):
        self.assertEqual(round_minutes(62, 15), 60)
        self.assertEqual(round_minutes(68, 15), 75)

    def test_halves_go_up(self):
        self.assertEqual(round_minutes(67, 15), 60)
        self.assertEqual(round_minutes(68, 15), 75)
        self.assertEqual(round_minutes(5, 10), 10)

    def test_odd_step(self):
        self.assertEqual(round_minutes(2, 3), 3)
        self.assertEqual(round_minutes(1, 3), 0)

class LabelTests(unittest.TestCase):
    def test_label(self):
        spans = [Span(541, 1034)]
        self.assertEqual(
            label_rounded(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_many_and_empty(self):
        spans = [Span(60, 120), Span(125, 185)]
        self.assertEqual(
            label_rounded(spans, 5),
            ["01:00-02:00 (1h 0m)", "02:05-03:05 (1h 0m)"],
        )
        self.assertEqual(label_rounded([], 5), [])

    def test_end_of_day(self):
        label = label_rounded([Span(1400, 1440)], 30)
        self.assertEqual(label, ["23:30-24:00 (0h 30m)"])

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            label_rounded([Span(61, 64)], 15)

class BadStepTests(unittest.TestCase):
    def test_bad_steps(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_rounded([], step)
